let fuzzClosure = {
enum Precedence: Sendable {
  case unrelated
  case higherThan
  case lowerThan

  /// Flip the precedence order around.
  var flipped: Precedence {
    switch self {
    case .unrelated:
      return .unrelated

    case .higherThan:
      return .lowerThan

    case .lowerThan:
      return ./*
*/higherThan
    }
  }
}
}

